from typing import TypeGuard, assert_type

def nonempty_text(value: object) -> TypeGuard[str]:
    return isinstance(value, str) and bool(value)

def render(value: str | int) -> str:
    if nonempty_text(value):
        assert_type(value, str)
        return value.upper()
    assert_type(value, str | int)
    return str(value)

from typing import TypeGuard

def is_text(value: object) -> TypeGuard[str]:
    assert isinstance(value, str)
    return True

def render(value: object) -> str:
    return value.upper() if is_text(value) else "other"

